INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('313', 'HBL_ENROLLMENT_REJECTED_TEMPLATE', '<p>&nbsp;</p><center><img src=\"https://ib1.himalayanbank.com/images/brand-login.png\" alt=\"hbl_logo\"  style=\"width:550px; display: block; margin-left: auto; margin-right: auto;\"/><br /><br /> <br /><table align=\"center\" style=\"width: 600px;\" ><tr><td style=\"border-style: solid; border-width: 6px; border-color: black;\"><br /><p  style=\"margin-left: 10px;\"> USER ACTIVATION NOTIFICATION <br /><br />Dear %firstName% %lastName%,<br /><br />Please note that your registration request for HBL Digital Banking cannot be completed due to some limitations. For details, please contact your branch or call us @ 01-5971399 or contact us through viber / whatsapp on 9803560838.<br /><br />We apologize for any inconvenience caused to you.<br /><br/><br />Thank you.<br /><br />Himalayan Bank<br/>Card & Digital Channel Center.<br ></p><br /></td></tr><tr><td><br /><b>Auto-generated Email Notification. Please do not reply to this email address.</b> <br /><br />The information in this mail is confidential and is intended solely for the addressee. Access to this mail by anyone else is unauthorized. Copying or further distribution beyond the original recipient may be unlawful. <br /><br /></td></tr></table></center>', 'Enrollment Rejected', 'Infinity', 'dbx_cl@infinity.com');
